      width: 100%;
      min-height: 3.4rem;
      margin-top: 1rem;
      border: 0;
      border-radius: var(--radius-md);
      padding: 0.9rem 1.25rem;
      color: #ffffff;
      background: var(--color-primary);
      box-shadow: 0 14px 30px #b9c5e7;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: background-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
