<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <header>
    <div class="brand" aria-label="Acme Support">
      <span class="brand-mark" aria-hidden="true">?</span>
      <span>Acme Support</span>
    </div>
  </header>

  <main id="main-content">
    <section class="hero" aria-labelledby="page-title">
      <p class="eyebrow">Support team</p>
      <h1 id="page-title">How can we help?</h1>
      <p>Send our product specialists a note and we will route your request to the right person.</p>
    </section>

    <section class="contact-card" aria-labelledby="form-title">
      <h2 class="form-heading" id="form-title">Contact support</h2>
      <p class="form-intro">Fields marked required must be completed before submitting.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">
            <span>Full name</span>
            <span class="required-note">Required</span>
          </label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
            aria-invalid="false"
          >
          <p class="field-error" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">
            <span>Email address</span>
            <span class="required-note">Required</span>
          </label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            inputmode="email"
            required
            aria-describedby="email-error"
            aria-invalid="false"
          >
          <p class="field-error" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">
            <span>Phone number</span>
            <span class="optional-note">Optional</span>
          </label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-help phone-error"
            aria-invalid="false"
          >
          <p class="field-help" id="phone-help">Use 10 digits, with optional spaces, dashes, parentheses, or a leading + country code.</p>
          <p class="field-error" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit support request</button>
        <p class="form-status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <footer>
    <p>Average first response time: one business day.</p>
  </footer>

  <script>
    const form = document.querySelector("#support-form");
    const statusMessage = document.querySelector("#form-status");

    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your full name.";
          }

          if (value.trim().length < 2) {
            return "Full name must be at least 2 characters.";
          }

          return "";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your email address.";
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return "Enter an email address in the format name@example.com.";
          }

          return "";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmedValue = value.trim();

          if (!trimmedValue) {
            return "";
          }

          if (!/^\+?[\d\s().-]{10,20}$/.test(trimmedValue)) {
            return "Enter a phone number using digits, spaces, dashes, parentheses, and an optional leading +.";
          }

          const digitCount = trimmedValue.replace(/\D/g, "").length;
          if (digitCount < 10 || digitCount > 15) {
            return "Enter a phone number with 10 to 15 digits.";
          }

          return "";
        }
      }
    };

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("blur", () => {
        validateField(field);
      });

      field.input.addEventListener("input", () => {
        statusMessage.textContent = "";
        if (field.input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      statusMessage.textContent = "";

      const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

      if (firstInvalidField) {
        firstInvalidField.input.focus();
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => setFieldError(field, ""));
      statusMessage.textContent = "Thanks. Your support request is ready to send.";
    });
  </script>
</body>
</html>
